import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"云汉","description":"","frontmatter":{"title":"云汉","date":"2026-11-09T00:00:00.000Z","seq":24,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/云汉.md","filePath":"blogs/诗经·大雅/云汉.md"}'),o={name:"blogs/诗经·大雅/云汉.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="云汉" tabindex="-1">云汉 <a class="header-anchor" href="#云汉" aria-label="Permalink to &quot;云汉&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">倬彼云汉，昭回于天。王曰：于乎！何辜今之人？天降丧乱，饥馑荐臻。</p><p class="poem-stanza">靡神不举，靡爱斯牲。圭壁既卒，宁莫我听？</p><p class="poem-stanza">旱既大甚，蕴隆虫虫。不殄禋祀，自郊徂宫。上下奠瘗，靡神不宗。</p><p class="poem-stanza">后稷不克，上帝不临。耗斁下土，宁丁我梗</p><p class="poem-stanza">旱既大甚，则不可推。兢兢业业，如霆如雷。周余黎民，靡有孑遗。</p><p class="poem-stanza">昊天上帝，则不我遗。胡不相畏？先祖于摧。</p><p class="poem-stanza">旱既大甚，则不可沮。赫赫炎炎，云我无所。大命近止，靡瞻靡顾。</p><p class="poem-stanza">群公先正，则不我助。父母先祖，胡宁忍予？</p><p class="poem-stanza">旱既大甚，涤涤山川。旱魃为虐，如惔如焚。我心惮暑，忧心如熏。</p><p class="poem-stanza">群公先正，则不我闻。昊天上帝，宁俾我遁？</p><p class="poem-stanza">旱既大甚，黾勉畏去。胡宁瘨我以旱？憯不知其故。祈年孔夙，方社不莫。</p><p class="poem-stanza">昊天上帝，则不我虞。</p><p class="poem-stanza">敬恭明神，宜无悔怒。旱既大甚，散无友纪。鞫哉庶正，疚哉冢宰。</p><p class="poem-stanza">趣马师氏，膳夫左右。靡人不周。无不能止，瞻卬昊天，云如何里！</p><p class="poem-stanza">瞻卬昊天，有嘒其星。大夫君子，昭假无赢。大命近止，无弃尔成。</p><p class="poem-stanza">何求为我。以戾庶正。瞻卬昊天，曷惠其宁？</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
